export class Sound{
 constructor(){this.context=null;this.volume=.55;}
 async resume(){if(!this.context){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;this.context=new C();const c=this.context;this.master=c.createGain();this.master.gain.value=0;this.master.connect(c.destination);this.engine=c.createOscillator();this.engine.type='sawtooth';this.engine2=c.createOscillator();this.engine2.type='triangle';const filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=650;this.engineGain=c.createGain();this.engineGain.gain.value=.03;this.engine.connect(filter);this.engine2.connect(filter);filter.connect(this.engineGain);this.engineGain.connect(this.master);this.engine.start();this.engine2.start();this.siren=c.createOscillator();this.siren.type='sine';this.sirenGain=c.createGain();this.sirenGain.gain.value=0;this.siren.connect(this.sirenGain);this.sirenGain.connect(this.master);this.siren.start();const buffer=c.createBuffer(1,c.sampleRate*2,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noise=c.createBufferSource();this.noise.buffer=buffer;this.noise.loop=true;this.noiseGain=c.createGain();this.noiseGain.gain.value=0;const nf=c.createBiquadFilter();nf.type='lowpass';nf.frequency.value=1300;this.noise.connect(nf);nf.connect(this.noiseGain);this.noiseGain.connect(this.master);this.noise.start();}await this.context.resume();}
 update(car,active,pursuit=null){if(!this.context)return;const t=this.context.currentTime;this.master.gain.setTargetAtTime(active?this.volume:0,t,.08);const rpm=1100+(Math.abs(car.speed)%12)/12*4700;this.engine.frequency.setTargetAtTime(rpm/60*2,t,.06);this.engine2.frequency.setTargetAtTime(rpm/60*1.5,t,.06);this.engineGain.gain.setTargetAtTime(.022+Math.abs(car.speed)/1600,t,.08);this.noiseGain.gain.setTargetAtTime(Math.abs(car.slip)*.3+(car.boosting?.025:0)+Math.abs(car.speed)*.00012+car.impact*.015,t,.04);this.siren.frequency.setTargetAtTime(850+Math.sin(t*5)*400,t,.03);this.sirenGain.gain.setTargetAtTime(active&&pursuit?Math.max(0,1-pursuit.nearestDistance/160)*.016:0,t,.1);}
}
